package com.github.zzave.teambalance.api.domain.model

import java.time.Instant
import java.util.UUID

/** The identity of a [BulletinPost]. Generated by the persistence adapter when the row is created. */
@JvmInline
value class BulletinPostId(val value: UUID) {
    override fun toString(): String = value.toString()
}

/** The Markdown of a [BulletinPost], trimmed, never blank, at most [MAX_LENGTH] characters (ADR-0048). */
@JvmInline
value class PostMarkdown private constructor(val value: String) {
    companion object {
        const val MAX_LENGTH = 5000

        fun of(raw: String): PostMarkdown {
            val markdown = raw.trim()
            require(markdown.isNotBlank()) { "A post must not be blank" }
            require(markdown.length <= MAX_LENGTH) { "A post must be at most $MAX_LENGTH characters" }
            return PostMarkdown(markdown)
        }

        /** For values read back from storage, which were validated when written. */
        fun stored(value: String) = PostMarkdown(value)
    }
}

/** One save of an existing [BulletinPost]: who and when, not the old text (ADR-0048). */
data class PostEdit(
    val editorId: UserId,
    val editedAt: Instant,
)

/** A message an Admin posts on the Team's Bulletin Board for every Member (ADR-0048). */
data class BulletinPost(
    val id: BulletinPostId,
    val markdown: PostMarkdown,
    val authorId: UserId,
    val postedAt: Instant,
    /** Oldest first. */
    val edits: List<PostEdit> = emptyList(),
)
